/**
 * EnterToTab2 - Nhấn Enter trong ô nhập điểm để chuyển xuống dòng dưới (cùng cột).
 * Dùng cho GridView + Telerik RadNumericTextBox (SubjectMarkEdit, BSims, ...).
 */
var EnterToTab2 = (function () {
    var initialized = false;

    function isMarkInput(input) {
        if (!input || input.tagName !== "INPUT") {
            return false;
        }
        if (input.type === "hidden") {
            return false;
        }

        var id = input.id || "";
        if (id.indexOf("txtMark") >= 0) {
            return true;
        }
        if (id.indexOf("txtTheoryExam") >= 0) {
            return true;
        }
        if (id.indexOf("txtPracticeExam") >= 0) {
            return true;
        }
        if (id.indexOf("txtExam") >= 0) {
            return true;
        }
        if (id.indexOf("txtSummary") >= 0) {
            return true;
        }
        if (id.indexOf("txtHS2") >= 0) {
            return true;
        }

        if (input.className && input.className.indexOf("riTextBox") >= 0) {
            return getParentTable(input) !== null;
        }

        return false;
    }

    function getParentTd(el) {
        var node = el;
        while (node && node.tagName !== "TD") {
            node = node.parentNode;
        }
        return node;
    }

    function getParentTr(el) {
        var node = el;
        while (node && node.tagName !== "TR") {
            node = node.parentNode;
        }
        return node;
    }

    function getParentTable(el) {
        var node = el;
        while (node && node.tagName !== "TABLE") {
            node = node.parentNode;
        }
        return node;
    }

    function getEditableInput(td) {
        var inputs, i, inp;

        if (!td) {
            return null;
        }

        inputs = td.getElementsByTagName("input");
        for (i = 0; i < inputs.length; i++) {
            inp = inputs[i];
            if (inp.type === "hidden") {
                continue;
            }
            if (inp.readOnly || inp.disabled) {
                continue;
            }
            if (inp.className && inp.className.indexOf("riTextBox") >= 0) {
                return inp;
            }
            if (inp.type === "text") {
                return inp;
            }
        }

        return null;
    }

    function focusMarkInput(input) {
        var radId, radControl;

        if (!input) {
            return;
        }

        radId = input.id;
        if (radId && radId.length > 5 && radId.lastIndexOf("_text") === radId.length - 5) {
            radId = radId.substring(0, radId.length - 5);
            if (typeof $find === "function") {
                radControl = $find(radId);
                if (radControl && typeof radControl.focus === "function") {
                    radControl.focus();
                    if (typeof radControl.selectText === "function") {
                        radControl.selectText();
                    } else if (input.select) {
                        input.select();
                    }
                    return;
                }
            }
        }

        input.focus();
        if (input.select) {
            input.select();
        }
    }

    function moveToNextRow(currentInput) {
        var td, tr, cellIndex, nextTr, nextInput;

        td = getParentTd(currentInput);
        tr = getParentTr(currentInput);
        if (!td || !tr) {
            return false;
        }

        cellIndex = td.cellIndex;
        nextTr = tr.nextSibling;
        while (nextTr && nextTr.nodeType !== 1) {
            nextTr = nextTr.nextSibling;
        }

        while (nextTr) {
            if (nextTr.tagName !== "TR") {
                nextTr = nextTr.nextSibling;
                continue;
            }

            if (nextTr.cells && nextTr.cells.length > cellIndex) {
                nextInput = getEditableInput(nextTr.cells[cellIndex]);
                if (nextInput) {
                    focusMarkInput(nextInput);
                    return true;
                }
            }

            nextTr = nextTr.nextSibling;
            while (nextTr && nextTr.nodeType !== 1) {
                nextTr = nextTr.nextSibling;
            }
        }

        return false;
    }

    function onKeyDown(e) {
        var key, target;

        e = e || window.event;
        key = e.keyCode || e.which;
        if (key !== 13) {
            return;
        }

        target = e.target || e.srcElement;
        if (!isMarkInput(target)) {
            return;
        }

        if (e.preventDefault) {
            e.preventDefault();
        } else {
            e.returnValue = false;
        }

        moveToNextRow(target);
        return false;
    }

    function init() {
        if (initialized) {
            return;
        }

        if (document.addEventListener) {
            document.addEventListener("keydown", onKeyDown, false);
        } else if (document.attachEvent) {
            document.attachEvent("onkeydown", onKeyDown);
        }

        initialized = true;
    }

    return {
        init: init
    };
})();

