function isDataRowInput(input) {
    var tr = getParentTr(input);
    if (!tr || !tr.parentNode || tr.parentNode.tagName !== "TBODY") {
        return false;
    }
    return true;
}

function isMarkGridTable(table) {
    var tableId, tableClass;

    if (!table) {
        return false;
    }

    tableId = table.id || "";
    tableClass = table.className || "";

    if (tableId.indexOf("gvData") >= 0) {
        return true;
    }
    if (tableClass.indexOf("Gridview") >= 0) {
        return true;
    }
    if (tableClass.indexOf("table-bordered") >= 0) {
        return true;
    }

    return false;
}

function isMarkInput(input) {
    var table;

    if (!input || input.tagName !== "INPUT") {
        return false;
    }
    if (input.type === "hidden") {
        return false;
    }
    if (input.readOnly || input.disabled) {
        return false;
    }
    if (!isDataRowInput(input)) {
        return false;
    }

    table = getParentTable(input);
    if (!isMarkGridTable(table)) {
        return false;
    }

    // Tất cả ô nhập trong lưới sổ điểm: RadNumericTextBox hoặc TextBox 1 dòng
    if (input.className && input.className.indexOf("riTextBox") >= 0) {
        return true;
    }
    if (input.type === "text") {
        return true;
    }

    return false;
}
